import { injectable, inject } from 'inversify';
import type { IssueReader, IssueWriter, Issue, Logger } from '@hcdevagent/shared';
import { SYMBOLS } from '@hcdevagent/shared';

/**
 * High-level module that coordinates issue tracker read/write operations.
 */
@injectable()
export class IssueTrackerModule {
  constructor(
    @inject(SYMBOLS.IssueReader) private readonly issueReader: IssueReader,
    @inject(SYMBOLS.IssueWriter) private readonly issueWriter: IssueWriter,
    @inject(SYMBOLS.Logger) private readonly logger: Logger,
  ) {}

  /** Fetches an issue by key. */
  public async fetchIssue(issueKey: string): Promise<Issue> {
    this.logger.info('Fetching issue', { issueKey });
    return this.issueReader.getIssue(issueKey);
  }

  /** Fetches issues using a JQL query. */
  public async searchIssues(query: string): Promise<ReadonlyArray<Issue>> {
    this.logger.info('Searching issues', { query });
    return this.issueReader.getIssues(query);
  }

  /** Transitions an issue and adds a comment. */
  public async transitionWithComment(
    issueKey: string,
    targetStatus: string,
    comment: string,
  ): Promise<void> {
    this.logger.info('Transitioning issue with comment', { issueKey, targetStatus });
    await this.issueWriter.transitionIssue(issueKey, targetStatus);
    await this.issueWriter.addComment(issueKey, comment);
  }
}

import { injectable, inject } from 'inversify';
import type { IssueReader, IssueWriter, IssueTrackerOperations, Issue, Comment, Logger } from '@hcdevagent/shared';
import { SYMBOLS, WORKFLOW_STATUSES, JIRA_CUSTOM_FIELDS, NotImplementedError } from '@hcdevagent/shared';

/**
 * High-level, workflow-aware module that composes IssueReader/IssueWriter
 * calls into composite operations consumed by the Conductor.
 * Implements IssueTrackerOperations from 3-interfaces.md §3.
 */
@injectable()
export class IssueTrackerModule implements IssueTrackerOperations {
    constructor(
        @inject(SYMBOLS.IssueReader) private readonly reader: IssueReader,
        @inject(SYMBOLS.IssueWriter) private readonly writer: IssueWriter,
        @inject(SYMBOLS.Logger) private readonly logger: Logger,
    ) {}

    // ── Phase 1 methods (fully implemented) ──────────────────────────────

    /** Poll for the next issue in SELECTED FOR TRIAGE status. */
    public async fetchNextIssue(): Promise<Issue | null> {
        this.logger.debug('Polling for next issue in Selected for Triage');
        const issues = await this.reader.fetchIssuesByStatus(WORKFLOW_STATUSES.SELECTED_FOR_TRIAGE);
        if (issues.length === 0) {
            return null;
        }
        return issues[0];
    }

    /** Transition issue to ISSUE INVESTIGATION. */
    public async startInvestigation(issueKey: string): Promise<void> {
        this.logger.info('Starting investigation', { issueKey });
        await this.writer.transitionStatus(issueKey, WORKFLOW_STATUSES.ISSUE_INVESTIGATION);
    }

    /** Transition to BLOCKED FOR PLAN CLARIFICATION + post comment with questions. */
    public async markBlockedForPlanClarification(issueKey: string, questions: string): Promise<void> {
        this.logger.info('Marking blocked for plan clarification', { issueKey });
        await this.writer.transitionStatus(issueKey, WORKFLOW_STATUSES.BLOCKED_FOR_PLAN_CLARIFICATION);
        await this.writer.addComment(issueKey, questions);
    }

    /** Write Description For AI field + transition to PLAN. */
    public async moveToPlan(issueKey: string, descriptionForAi: string): Promise<void> {
        this.logger.info('Moving to Plan', { issueKey });
        await this.writer.updateCustomField(issueKey, JIRA_CUSTOM_FIELDS.DESCRIPTION_FOR_AI, descriptionForAi);
        await this.writer.transitionStatus(issueKey, WORKFLOW_STATUSES.PLAN);
    }

    /** Transition to FAILURE + write Failure Reason field + comment. */
    public async markFailed(issueKey: string, reason: string): Promise<void> {
        this.logger.info('Marking issue as failed', { issueKey, reason });
        await this.writer.updateCustomField(issueKey, JIRA_CUSTOM_FIELDS.FAILURE_REASON, reason);
        await this.writer.transitionStatus(issueKey, WORKFLOW_STATUSES.FAILURE);
        await this.writer.addComment(issueKey, `Agent failure: ${reason}`);
    }

    /** Read the latest human comment (for clarification responses). */
    public async getLatestHumanReply(issueKey: string): Promise<Comment | null> {
        return this.reader.getLatestComment(issueKey);
    }

    /** Read current status (for detecting cancellation / external changes). */
    public async getCurrentStatus(issueKey: string): Promise<string> {
        return this.reader.getStatus(issueKey);
    }

    // ── Read convenience methods (fully implemented) ─────────────────────

    /** Read Description For AI custom field. */
    public async getDescriptionForAi(issueKey: string): Promise<string | null> {
        return this.reader.getCustomField(issueKey, JIRA_CUSTOM_FIELDS.DESCRIPTION_FOR_AI);
    }

    /** Read Implementation Plan custom field. */
    public async getPlan(issueKey: string): Promise<string | null> {
        return this.reader.getCustomField(issueKey, JIRA_CUSTOM_FIELDS.IMPLEMENTATION_PLAN);
    }

    /** Read Implementation Plan For AI custom field. */
    public async getPlanForAi(issueKey: string): Promise<string | null> {
        return this.reader.getCustomField(issueKey, JIRA_CUSTOM_FIELDS.IMPLEMENTATION_PLAN_FOR_AI);
    }

    /** Read Branch Name custom field. */
    public async getBranchName(issueKey: string): Promise<string | null> {
        return this.reader.getCustomField(issueKey, JIRA_CUSTOM_FIELDS.BRANCH_NAME);
    }

    /** Read PR URL custom field. */
    public async getPrUrl(issueKey: string): Promise<string | null> {
        return this.reader.getCustomField(issueKey, JIRA_CUSTOM_FIELDS.PR_URL);
    }

    // ── Phase 2+ methods (not yet implemented) ───────────────────────────

    /** Write Implementation Plan + Implementation Plan For AI fields + transition to PLAN REVIEW. */
    public async moveToPlanReview(issueKey: string, plan: string, planForAi: string): Promise<void> {
        throw new NotImplementedError('moveToPlanReview', { issueKey });
    }

    /** Transition to IN PROGRESS + write Branch Name field. */
    public async startImplementation(issueKey: string, branchName: string): Promise<void> {
        throw new NotImplementedError('startImplementation', { issueKey });
    }

    /** Transition to BLOCKED FOR CODE CLARIFICATION + post comment. */
    public async markBlockedForCodeClarification(issueKey: string, questions: string): Promise<void> {
        throw new NotImplementedError('markBlockedForCodeClarification', { issueKey });
    }

    /** Transition to IN PROGRESS (after code clarification resolved). */
    public async resumeImplementation(issueKey: string): Promise<void> {
        throw new NotImplementedError('resumeImplementation', { issueKey });
    }

    /** Transition to CODE COMMITTED. */
    public async markCodeCommitted(issueKey: string): Promise<void> {
        throw new NotImplementedError('markCodeCommitted', { issueKey });
    }

    /** Transition to PR IN REVIEW + write PR URL field + comment. */
    public async markPrInReview(issueKey: string, prUrl: string): Promise<void> {
        throw new NotImplementedError('markPrInReview', { issueKey });
    }

    /** Transition to PR APPROVED. */
    public async markPrApproved(issueKey: string): Promise<void> {
        throw new NotImplementedError('markPrApproved', { issueKey });
    }

    /** Transition to DONE. */
    public async markDone(issueKey: string): Promise<void> {
        throw new NotImplementedError('markDone', { issueKey });
    }

    /** Transition to PR CHANGES REQUESTED + comment. */
    public async markPrChangesRequested(issueKey: string, reviewComment: string): Promise<void> {
        throw new NotImplementedError('markPrChangesRequested', { issueKey });
    }
}

import { injectable } from 'inversify';
import type { EventBus } from '@hcdevagent/shared';

/** Handler function type for event bus subscriptions. */
type EventHandler = (payload: unknown) => void;

/**
 * Simple in-process event bus using a Map of event handlers.
 */
@injectable()
export class InProcessEventBus implements EventBus {
  private readonly handlers: Map<string, Set<EventHandler>> = new Map();

  /** Publishes an event to all registered handlers. */
  public publish(eventName: string, payload: unknown): void {
    const eventHandlers = this.handlers.get(eventName);
    if (eventHandlers) {
      for (const handler of eventHandlers) {
        handler(payload);
      }
    }
  }

  /** Subscribes a handler to a specific event. */
  public subscribe(eventName: string, handler: EventHandler): void {
    if (!this.handlers.has(eventName)) {
      this.handlers.set(eventName, new Set());
    }
    this.handlers.get(eventName)!.add(handler);
  }

  /** Unsubscribes a handler from a specific event. */
  public unsubscribe(eventName: string, handler: EventHandler): void {
    const eventHandlers = this.handlers.get(eventName);
    if (eventHandlers) {
      eventHandlers.delete(handler);
    }
  }
}

import { injectable } from 'inversify';
import type { EventBus } from '@hcdevagent/shared';

/** Handler function type for event bus subscriptions. */
type EventHandler = (payload: unknown) => void;

/**
 * Simple in-process event bus using a Map of event handlers.
 */
@injectable()
export class InProcessEventBus implements EventBus {
    private readonly handlers: Map<string, Set<EventHandler>> = new Map();

    /** Publishes an event to all registered handlers. */
    public emit(eventName: string, payload: unknown): void {
        const eventHandlers = this.handlers.get(eventName);
        if (eventHandlers) {
            for (const handler of eventHandlers) {
                handler(payload);
            }
        }
    }

    /** Registers a handler for a specific event. */
    public on(eventName: string, handler: EventHandler): void {
        if (!this.handlers.has(eventName)) {
            this.handlers.set(eventName, new Set());
        }
        this.handlers.get(eventName)!.add(handler);
    }

    /** Removes a handler from a specific event. */
    public off(eventName: string, handler: EventHandler): void {
        const eventHandlers = this.handlers.get(eventName);
        if (eventHandlers) {
            eventHandlers.delete(handler);
        }
    }
}

import { injectable, inject } from 'inversify';
import type { IssueReader, Issue, ConfigProvider, Logger } from '@hcdevagent/shared';
import { SYMBOLS, IntegrationError } from '@hcdevagent/shared';

/**
 * Reads issues from the Jira REST API.
 */
@injectable()
export class JiraIssueReader implements IssueReader {
  private readonly baseUrl: string;
  private readonly authHeader: string;

  constructor(
    @inject(SYMBOLS.ConfigProvider) configProvider: ConfigProvider,
    @inject(SYMBOLS.Logger) private readonly logger: Logger,
  ) {
    this.baseUrl = configProvider.getRequired('JIRA_BASE_URL');
    const email = configProvider.getRequired('JIRA_USER_EMAIL');
    const token = configProvider.getRequired('JIRA_API_TOKEN');
    this.authHeader = `Basic ${Buffer.from(`${email}:${token}`).toString('base64')}`;
  }

  /** Fetches a single issue by key from Jira. */
  public async getIssue(issueKey: string): Promise<Issue> {
    this.logger.debug('Fetching issue from Jira', { issueKey });
    try {
      const response = await fetch(`${this.baseUrl}/rest/api/3/issue/${issueKey}`, {
        headers: {
          Authorization: this.authHeader,
          Accept: 'application/json',
        },
      });
      if (!response.ok) {
        throw new IntegrationError(`Jira API returned ${response.status}`, {
          issueKey,
          status: response.status,
        });
      }
      const data = (await response.json()) as Record<string, unknown>;
      return this.mapToIssue(data);
    } catch (error) {
      if (error instanceof IntegrationError) throw error;
      throw new IntegrationError('Failed to fetch issue from Jira', {
        issueKey,
        originalError: String(error),
      });
    }
  }

  /** Fetches issues matching a JQL query from Jira. */
  public async getIssues(query: string): Promise<ReadonlyArray<Issue>> {
    this.logger.debug('Searching issues in Jira', { query });
    try {
      const response = await fetch(
        `${this.baseUrl}/rest/api/3/search?jql=${encodeURIComponent(query)}`,
        {
          headers: {
            Authorization: this.authHeader,
            Accept: 'application/json',
          },
        },
      );
      if (!response.ok) {
        throw new IntegrationError(`Jira search API returned ${response.status}`, {
          query,
          status: response.status,
        });
      }
      const data = (await response.json()) as { issues: ReadonlyArray<Record<string, unknown>> };
      return data.issues.map((issue) => this.mapToIssue(issue));
    } catch (error) {
      if (error instanceof IntegrationError) throw error;
      throw new IntegrationError('Failed to search issues in Jira', {
        query,
        originalError: String(error),
      });
    }
  }

  /** Maps raw Jira API response to the Issue domain type. */
  private mapToIssue(data: Record<string, unknown>): Issue {
    const fields = data['fields'] as Record<string, unknown> | undefined;
    return {
      id: String(data['id'] ?? ''),
      key: String(data['key'] ?? ''),
      summary: String(fields?.['summary'] ?? ''),
      description: String(fields?.['description'] ?? ''),
      status: String((fields?.['status'] as Record<string, unknown>)?.['name'] ?? ''),
      assignee: fields?.['assignee']
        ? String((fields['assignee'] as Record<string, unknown>)['displayName'])
        : null,
      labels: (fields?.['labels'] as ReadonlyArray<string>) ?? [],
      comments: [],
      createdAt: String(fields?.['created'] ?? ''),
      updatedAt: String(fields?.['updated'] ?? ''),
    };
  }
}

import { injectable, inject } from 'inversify';
import type { IssueReader, Issue, Comment, ConfigProvider, Logger } from '@hcdevagent/shared';
import { SYMBOLS, IntegrationError, JIRA_CUSTOM_FIELDS } from '@hcdevagent/shared';

/** Shape of a raw Jira issue from the API. */
interface JiraIssueRaw {
    readonly id: string;
    readonly key: string;
    readonly fields: Record<string, unknown>;
}

/** Shape of a raw Jira comment from the API. */
interface JiraCommentRaw {
    readonly id: string;
    readonly author?: { readonly displayName?: string };
    readonly body?: unknown;
    readonly created?: string;
}

/** Shape of the Jira search response. */
interface JiraSearchResponse {
    readonly issues: ReadonlyArray<JiraIssueRaw>;
}

/** Shape of the Jira comments response. */
interface JiraCommentsResponse {
    readonly comments: ReadonlyArray<JiraCommentRaw>;
}

/**
 * Reads issues from the Jira Cloud REST API v3.
 * Implements all 6 methods from 3-interfaces.md §1.
 */
@injectable()
export class JiraIssueReader implements IssueReader {
    private readonly baseUrl: string;
    private readonly authHeader: string;

    constructor(
        @inject(SYMBOLS.ConfigProvider) configProvider: ConfigProvider,
        @inject(SYMBOLS.Logger) private readonly logger: Logger,
    ) {
        this.baseUrl = configProvider.getRequired('JIRA_BASE_URL');
        const email = configProvider.getRequired('JIRA_USER_EMAIL');
        const token = configProvider.getRequired('JIRA_API_TOKEN');
        this.authHeader = `Basic ${Buffer.from(`${email}:${token}`).toString('base64')}`;
    }

    /** Fetch all issues currently in the given workflow status. */
    public async fetchIssuesByStatus(statusName: string): Promise<ReadonlyArray<Issue>> {
        this.logger.debug('Fetching issues by status', { statusName });
        const jql = `status = "${statusName}" ORDER BY created ASC`;
        const response = await this.jiraGet<JiraSearchResponse>(
            `/rest/api/3/search?jql=${encodeURIComponent(jql)}&fields=*all`,
        );
        return response.issues.map((raw) => this.mapToIssue(raw));
    }

    /** Fetch full issue details by key. */
    public async getIssue(issueKey: string): Promise<Issue> {
        this.logger.debug('Fetching issue', { issueKey });
        const raw = await this.jiraGet<JiraIssueRaw>(`/rest/api/3/issue/${issueKey}?fields=*all`);
        return this.mapToIssue(raw);
    }

    /** Fetch all comments on an issue, ordered chronologically. */
    public async getComments(issueKey: string): Promise<ReadonlyArray<Comment>> {
        this.logger.debug('Fetching comments', { issueKey });
        const response = await this.jiraGet<JiraCommentsResponse>(
            `/rest/api/3/issue/${issueKey}/comment?orderBy=created`,
        );
        return response.comments.map((raw) => this.mapToComment(raw));
    }

    /** Fetch the most recent comment. */
    public async getLatestComment(issueKey: string): Promise<Comment | null> {
        const comments = await this.getComments(issueKey);
        return comments.length > 0 ? comments[comments.length - 1] : null;
    }

    /** Read the value of a custom field. */
    public async getCustomField(issueKey: string, fieldName: string): Promise<string | null> {
        this.logger.debug('Reading custom field', { issueKey, fieldName });
        const issue = await this.getIssue(issueKey);
        return issue.customFields[fieldName] ?? null;
    }

    /** Read the current workflow status of an issue. */
    public async getStatus(issueKey: string): Promise<string> {
        this.logger.debug('Reading status', { issueKey });
        const issue = await this.getIssue(issueKey);
        return issue.status;
    }

    /** Generic GET request to Jira API. */
    private async jiraGet<T>(path: string): Promise<T> {
        try {
            const response = await fetch(`${this.baseUrl}${path}`, {
                headers: {
                    Authorization: this.authHeader,
                    Accept: 'application/json',
                },
            });
            if (!response.ok) {
                throw new IntegrationError(`Jira API returned ${response.status}`, {
                    path,
                    status: response.status,
                });
            }
            return (await response.json()) as T;
        } catch (error) {
            if (error instanceof IntegrationError) throw error;
            throw new IntegrationError('Failed to communicate with Jira API', {
                path,
                originalError: String(error),
            });
        }
    }

    /** Maps raw Jira API response to the Issue domain type. */
    private mapToIssue(raw: JiraIssueRaw): Issue {
        const fields = raw.fields;
        const statusObj = fields['status'] as Record<string, unknown> | undefined;
        const assigneeObj = fields['assignee'] as Record<string, unknown> | undefined;
        const commentObj = fields['comment'] as JiraCommentsResponse | undefined;

        // Extract description text from ADF or plain text
        const descriptionRaw = fields['description'];
        const description = typeof descriptionRaw === 'string'
            ? descriptionRaw
            : this.extractTextFromAdf(descriptionRaw);

        // Build custom fields map from known field keys
        const customFields: Record<string, string | null> = {};
        for (const fieldKey of Object.values(JIRA_CUSTOM_FIELDS)) {
            const value = fields[fieldKey];
            customFields[fieldKey] = typeof value === 'string' ? value : null;
        }

        return {
            id: String(raw.id),
            key: String(raw.key),
            summary: String(fields['summary'] ?? ''),
            description,
            status: String(statusObj?.['name'] ?? ''),
            assignee: assigneeObj ? String(assigneeObj['displayName'] ?? '') : null,
            labels: (fields['labels'] as ReadonlyArray<string>) ?? [],
            comments: commentObj?.comments
                ? commentObj.comments.map((c) => this.mapToComment(c))
                : [],
            customFields,
            createdAt: String(fields['created'] ?? ''),
            updatedAt: String(fields['updated'] ?? ''),
        };
    }

    /** Maps a raw Jira comment to the Comment domain type. */
    private mapToComment(raw: JiraCommentRaw): Comment {
        const bodyRaw = raw.body;
        const body = typeof bodyRaw === 'string'
            ? bodyRaw
            : this.extractTextFromAdf(bodyRaw);

        return {
            id: String(raw.id),
            author: String(raw.author?.displayName ?? 'Unknown'),
            body,
            createdAt: String(raw.created ?? ''),
        };
    }

    /** Extracts plain text from an ADF (Atlassian Document Format) object. */
    private extractTextFromAdf(adf: unknown): string {
        if (!adf || typeof adf !== 'object') return '';
        const node = adf as Record<string, unknown>;
        if (node['type'] === 'text' && typeof node['text'] === 'string') {
            return node['text'];
        }
        const content = node['content'] as ReadonlyArray<unknown> | undefined;
        if (Array.isArray(content)) {
            return content.map((child) => this.extractTextFromAdf(child)).join('');
        }
        return '';
    }
}

import { injectable, inject } from 'inversify';
import type { IssueWriter, ConfigProvider, Logger } from '@hcdevagent/shared';
import { SYMBOLS, IntegrationError } from '@hcdevagent/shared';

/**
 * Writes updates to the Jira REST API.
 */
@injectable()
export class JiraIssueWriter implements IssueWriter {
  private readonly baseUrl: string;
  private readonly authHeader: string;

  constructor(
    @inject(SYMBOLS.ConfigProvider) configProvider: ConfigProvider,
    @inject(SYMBOLS.Logger) private readonly logger: Logger,
  ) {
    this.baseUrl = configProvider.getRequired('JIRA_BASE_URL');
    const email = configProvider.getRequired('JIRA_USER_EMAIL');
    const token = configProvider.getRequired('JIRA_API_TOKEN');
    this.authHeader = `Basic ${Buffer.from(`${email}:${token}`).toString('base64')}`;
  }

  /** Transitions an issue to a new status. */
  public async transitionIssue(issueKey: string, targetStatus: string): Promise<void> {
    this.logger.info('Transitioning issue', { issueKey, targetStatus });
    try {
      const response = await fetch(
        `${this.baseUrl}/rest/api/3/issue/${issueKey}/transitions`,
        {
          method: 'POST',
          headers: {
            Authorization: this.authHeader,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            transition: { id: targetStatus },
          }),
        },
      );
      if (!response.ok) {
        throw new IntegrationError(`Jira transition API returned ${response.status}`, {
          issueKey,
          targetStatus,
          status: response.status,
        });
      }
    } catch (error) {
      if (error instanceof IntegrationError) throw error;
      throw new IntegrationError('Failed to transition issue in Jira', {
        issueKey,
        targetStatus,
        originalError: String(error),
      });
    }
  }

  /** Adds a comment to an issue in Jira. */
  public async addComment(issueKey: string, body: string): Promise<void> {
    this.logger.debug('Adding comment to issue', { issueKey });
    try {
      const response = await fetch(
        `${this.baseUrl}/rest/api/3/issue/${issueKey}/comment`,
        {
          method: 'POST',
          headers: {
            Authorization: this.authHeader,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            body: {
              type: 'doc',
              version: 1,
              content: [
                {
                  type: 'paragraph',
                  content: [{ type: 'text', text: body }],
                },
              ],
            },
          }),
        },
      );
      if (!response.ok) {
        throw new IntegrationError(`Jira comment API returned ${response.status}`, {
          issueKey,
          status: response.status,
        });
      }
    } catch (error) {
      if (error instanceof IntegrationError) throw error;
      throw new IntegrationError('Failed to add comment in Jira', {
        issueKey,
        originalError: String(error),
      });
    }
  }

  /** Updates custom fields on an issue. */
  public async updateFields(
    issueKey: string,
    fields: Record<string, unknown>,
  ): Promise<void> {
    this.logger.debug('Updating issue fields', { issueKey, fields });
    try {
      const response = await fetch(
        `${this.baseUrl}/rest/api/3/issue/${issueKey}`,
        {
          method: 'PUT',
          headers: {
            Authorization: this.authHeader,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ fields }),
        },
      );
      if (!response.ok) {
        throw new IntegrationError(`Jira update API returned ${response.status}`, {
          issueKey,
          status: response.status,
        });
      }
    } catch (error) {
      if (error instanceof IntegrationError) throw error;
      throw new IntegrationError('Failed to update issue fields in Jira', {
        issueKey,
        originalError: String(error),
      });
    }
  }
}

import { injectable, inject } from 'inversify';
import type { IssueWriter, ConfigProvider, Logger } from '@hcdevagent/shared';
import { SYMBOLS, IntegrationError } from '@hcdevagent/shared';

/** Shape of a Jira transition object. */
interface JiraTransition {
    readonly id: string;
    readonly name: string;
    readonly to: { readonly name: string };
}

/** Shape of the Jira transitions response. */
interface JiraTransitionsResponse {
    readonly transitions: ReadonlyArray<JiraTransition>;
}

/**
 * Writes updates to the Jira Cloud REST API v3.
 * Implements all 3 methods from 3-interfaces.md §2.
 */
@injectable()
export class JiraIssueWriter implements IssueWriter {
    private readonly baseUrl: string;
    private readonly authHeader: string;

    constructor(
        @inject(SYMBOLS.ConfigProvider) configProvider: ConfigProvider,
        @inject(SYMBOLS.Logger) private readonly logger: Logger,
    ) {
        this.baseUrl = configProvider.getRequired('JIRA_BASE_URL');
        const email = configProvider.getRequired('JIRA_USER_EMAIL');
        const token = configProvider.getRequired('JIRA_API_TOKEN');
        this.authHeader = `Basic ${Buffer.from(`${email}:${token}`).toString('base64')}`;
    }

    /** Move the issue to a new workflow status by name. Looks up the transition ID first. */
    public async transitionStatus(issueKey: string, statusName: string): Promise<void> {
        this.logger.info('Transitioning issue', { issueKey, statusName });
        const transitionId = await this.findTransitionId(issueKey, statusName);
        await this.jiraPost(
            `/rest/api/3/issue/${issueKey}/transitions`,
            { transition: { id: transitionId } },
        );
    }

    /** Post a comment on the issue in ADF format. */
    public async addComment(issueKey: string, body: string): Promise<void> {
        this.logger.debug('Adding comment to issue', { issueKey });
        await this.jiraPost(
            `/rest/api/3/issue/${issueKey}/comment`,
            {
                body: {
                    type: 'doc',
                    version: 1,
                    content: [
                        {
                            type: 'paragraph',
                            content: [{ type: 'text', text: body }],
                        },
                    ],
                },
            },
        );
    }

    /** Write a value to a custom Jira field. */
    public async updateCustomField(issueKey: string, fieldName: string, value: string): Promise<void> {
        this.logger.debug('Updating custom field', { issueKey, fieldName });
        await this.jiraPut(
            `/rest/api/3/issue/${issueKey}`,
            { fields: { [fieldName]: value } },
        );
    }

    /** Looks up the transition ID for a target status name. */
    private async findTransitionId(issueKey: string, statusName: string): Promise<string> {
        const response = await this.jiraGet<JiraTransitionsResponse>(
            `/rest/api/3/issue/${issueKey}/transitions`,
        );
        const transition = response.transitions.find(
            (t) => t.to.name.toLowerCase() === statusName.toLowerCase()
                || t.name.toLowerCase() === statusName.toLowerCase(),
        );
        if (!transition) {
            throw new IntegrationError(
                `No transition found to status "${statusName}"`,
                { issueKey, statusName, available: response.transitions.map((t) => t.to.name) },
            );
        }
        return transition.id;
    }

    /** Generic GET request to Jira API. */
    private async jiraGet<T>(path: string): Promise<T> {
        try {
            const response = await fetch(`${this.baseUrl}${path}`, {
                headers: {
                    Authorization: this.authHeader,
                    Accept: 'application/json',
                },
            });
            if (!response.ok) {
                throw new IntegrationError(`Jira API returned ${response.status}`, {
                    path,
                    status: response.status,
                });
            }
            return (await response.json()) as T;
        } catch (error) {
            if (error instanceof IntegrationError) throw error;
            throw new IntegrationError('Jira API request failed', { path, originalError: String(error) });
        }
    }

    /** Generic POST request to Jira API. */
    private async jiraPost(path: string, body: unknown): Promise<void> {
        try {
            const response = await fetch(`${this.baseUrl}${path}`, {
                method: 'POST',
                headers: {
                    Authorization: this.authHeader,
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(body),
            });
            if (!response.ok) {
                throw new IntegrationError(`Jira API POST returned ${response.status}`, {
                    path,
                    status: response.status,
                });
            }
        } catch (error) {
            if (error instanceof IntegrationError) throw error;
            throw new IntegrationError('Jira API POST request failed', { path, originalError: String(error) });
        }
    }

    /** Generic PUT request to Jira API. */
    private async jiraPut(path: string, body: unknown): Promise<void> {
        try {
            const response = await fetch(`${this.baseUrl}${path}`, {
                method: 'PUT',
                headers: {
                    Authorization: this.authHeader,
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(body),
            });
            if (!response.ok) {
                throw new IntegrationError(`Jira API PUT returned ${response.status}`, {
                    path,
                    status: response.status,
                });
            }
        } catch (error) {
            if (error instanceof IntegrationError) throw error;
            throw new IntegrationError('Jira API PUT request failed', { path, originalError: String(error) });
        }
    }
}

import { injectable, inject } from 'inversify';
import pino from 'pino';
import type { Logger, ConfigProvider } from '@hcdevagent/shared';
import { SYMBOLS } from '@hcdevagent/shared';

/**
 * Pino-based logger implementation.
 */
@injectable()
export class PinoLogger implements Logger {
  private readonly pinoInstance: pino.Logger;

  constructor(@inject(SYMBOLS.ConfigProvider) configProvider: ConfigProvider) {
    const level = configProvider.getOptional('AGENT_LOG_LEVEL') ?? 'info';
    this.pinoInstance = pino({ level });
  }

  /** @internal Constructor for child logger instances. */
  private static fromInstance(instance: pino.Logger): PinoLogger {
    const logger = Object.create(PinoLogger.prototype) as PinoLogger;
    (logger as unknown as { pinoInstance: pino.Logger }).pinoInstance = instance;
    return logger;
  }

  /** Logs a debug-level message. */
  public debug(message: string, context?: Record<string, unknown>): void {
    this.pinoInstance.debug(context ?? {}, message);
  }

  /** Logs an info-level message. */
  public info(message: string, context?: Record<string, unknown>): void {
    this.pinoInstance.info(context ?? {}, message);
  }

  /** Logs a warn-level message. */
  public warn(message: string, context?: Record<string, unknown>): void {
    this.pinoInstance.warn(context ?? {}, message);
  }

  /** Logs an error-level message. */
  public error(message: string, context?: Record<string, unknown>): void {
    this.pinoInstance.error(context ?? {}, message);
  }

  /** Creates a child logger with additional context. */
  public child(context: Record<string, unknown>): Logger {
    const childInstance = this.pinoInstance.child(context);
    return PinoLogger.fromInstance(childInstance);
  }
}

