import { describe, it, expect, vi, beforeEach } from 'vitest';
import type { ConfigProvider, Logger } from '@hcdevagent/shared';
import { IntegrationError, JIRA_CUSTOM_FIELDS } from '@hcdevagent/shared';
import { JiraIssueReader } from '../../services/issueTracker/JiraIssueReader.js';

/** Creates a mock ConfigProvider with Jira config. */
const createMockConfig = (): ConfigProvider => ({
    getRequired: vi.fn().mockImplementation((key: string) => {
        const map: Record<string, string> = {
            JIRA_BASE_URL: 'https://test.atlassian.net',
            JIRA_USER_EMAIL: 'test@example.com',
            JIRA_API_TOKEN: 'test-token',
        };
        return map[key] ?? 'default';
    }),
    getOptional: vi.fn(),
    getRequiredNumber: vi.fn(),
    getOptionalNumber: vi.fn(),
});

/** Creates a mock Logger. */
const createMockLogger = (): Logger => ({
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    debug: vi.fn(),
    child: vi.fn().mockReturnThis(),
});

/** Sample Jira issue response. */
const sampleJiraIssue = {
    id: '10001',
    key: 'TEST-1',
    fields: {
        summary: 'Test issue',
        description: 'A test description',
        status: { name: 'Selected for Triage' },
        assignee: { displayName: 'Test User' },
        labels: ['bug'],
        created: '2026-01-01T00:00:00.000Z',
        updated: '2026-01-02T00:00:00.000Z',
        comment: {
            comments: [
                {
                    id: 'c1',
                    author: { displayName: 'Author' },
                    body: 'A comment',
                    created: '2026-01-01T12:00:00.000Z',
                },
            ],
        },
        [JIRA_CUSTOM_FIELDS.DESCRIPTION_FOR_AI]: 'AI description',
    },
};

describe('JiraIssueReader', () => {
    let reader: JiraIssueReader;
    let fetchMock: ReturnType<typeof vi.fn>;

    beforeEach(() => {
        fetchMock = vi.fn();
        global.fetch = fetchMock;
        reader = new JiraIssueReader(createMockConfig(), createMockLogger());
    });

    describe('fetchIssuesByStatus', () => {
        it('should return mapped issues from search API', async () => {
            fetchMock.mockResolvedValue({
                ok: true,
                json: () => Promise.resolve({ issues: [sampleJiraIssue] }),
            });

            const issues = await reader.fetchIssuesByStatus('Selected for Triage');
            expect(issues).toHaveLength(1);
            expect(issues[0].key).toBe('TEST-1');
            expect(issues[0].summary).toBe('Test issue');
        });

        it('should return empty array when no issues found', async () => {
            fetchMock.mockResolvedValue({
                ok: true,
                json: () => Promise.resolve({ issues: [] }),
            });

            const issues = await reader.fetchIssuesByStatus('Selected for Triage');
            expect(issues).toHaveLength(0);
        });

        it('should throw IntegrationError on non-OK response', async () => {
            fetchMock.mockResolvedValue({ ok: false, status: 500 });
            await expect(reader.fetchIssuesByStatus('Selected for Triage')).rejects.toThrow(IntegrationError);
        });

        it('should throw IntegrationError on network failure', async () => {
            fetchMock.mockRejectedValue(new Error('Network error'));
            await expect(reader.fetchIssuesByStatus('Selected for Triage')).rejects.toThrow(IntegrationError);
        });
    });

    describe('getIssue', () => {
        it('should return a mapped issue', async () => {
            fetchMock.mockResolvedValue({
                ok: true,
                json: () => Promise.resolve(sampleJiraIssue),
            });

            const issue = await reader.getIssue('TEST-1');
            expect(issue.key).toBe('TEST-1');
            expect(issue.status).toBe('Selected for Triage');
            expect(issue.assignee).toBe('Test User');
        });

        it('should map custom fields correctly', async () => {
            fetchMock.mockResolvedValue({
                ok: true,
                json: () => Promise.resolve(sampleJiraIssue),
            });

            const issue = await reader.getIssue('TEST-1');
            expect(issue.customFields[JIRA_CUSTOM_FIELDS.DESCRIPTION_FOR_AI]).toBe('AI description');
        });

        it('should handle null assignee', async () => {
            const issueNoAssignee = {
                ...sampleJiraIssue,
                fields: { ...sampleJiraIssue.fields, assignee: null },
            };
            fetchMock.mockResolvedValue({
                ok: true,
                json: () => Promise.resolve(issueNoAssignee),
            });

            const issue = await reader.getIssue('TEST-1');
            expect(issue.assignee).toBeNull();
        });

        it('should throw IntegrationError on failure', async () => {
            fetchMock.mockResolvedValue({ ok: false, status: 404 });
            await expect(reader.getIssue('MISSING-1')).rejects.toThrow(IntegrationError);
        });
    });

    describe('getComments', () => {
        it('should return mapped comments', async () => {
            fetchMock.mockResolvedValue({
                ok: true,
                json: () => Promise.resolve({
                    comments: [
                        { id: 'c1', author: { displayName: 'User' }, body: 'Hello', created: '2026-01-01' },
                    ],
                }),
            });

            const comments = await reader.getComments('TEST-1');
            expect(comments).toHaveLength(1);
            expect(comments[0].author).toBe('User');
            expect(comments[0].body).toBe('Hello');
        });

        it('should return empty array when no comments', async () => {
            fetchMock.mockResolvedValue({
                ok: true,
                json: () => Promise.resolve({ comments: [] }),
            });

            const comments = await reader.getComments('TEST-1');
            expect(comments).toHaveLength(0);
        });
    });

    describe('getLatestComment', () => {
        it('should return the last comment', async () => {
            fetchMock.mockResolvedValue({
                ok: true,
                json: () => Promise.resolve({
                    comments: [
                        { id: 'c1', author: { displayName: 'User' }, body: 'First', created: '2026-01-01' },
                        { id: 'c2', author: { displayName: 'User' }, body: 'Last', created: '2026-01-02' },
                    ],
                }),
            });

            const comment = await reader.getLatestComment('TEST-1');
            expect(comment).not.toBeNull();
            expect(comment!.body).toBe('Last');
        });

        it('should return null when no comments', async () => {
            fetchMock.mockResolvedValue({
                ok: true,
                json: () => Promise.resolve({ comments: [] }),
            });

            const comment = await reader.getLatestComment('TEST-1');
            expect(comment).toBeNull();
        });
    });

    describe('getCustomField', () => {
        it('should return the custom field value', async () => {
            fetchMock.mockResolvedValue({
                ok: true,
                json: () => Promise.resolve(sampleJiraIssue),
            });

            const value = await reader.getCustomField('TEST-1', JIRA_CUSTOM_FIELDS.DESCRIPTION_FOR_AI);
            expect(value).toBe('AI description');
        });

        it('should return null for missing custom field', async () => {
            fetchMock.mockResolvedValue({
                ok: true,
                json: () => Promise.resolve(sampleJiraIssue),
            });

            const value = await reader.getCustomField('TEST-1', JIRA_CUSTOM_FIELDS.BRANCH_NAME);
            expect(value).toBeNull();
        });
    });

    describe('getStatus', () => {
        it('should return the issue status name', async () => {
            fetchMock.mockResolvedValue({
                ok: true,
                json: () => Promise.resolve(sampleJiraIssue),
            });

            const status = await reader.getStatus('TEST-1');
            expect(status).toBe('Selected for Triage');
        });
    });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import type { ConfigProvider, Logger } from '@hcdevagent/shared';
import { IntegrationError } from '@hcdevagent/shared';
import { JiraIssueWriter } from '../../services/issueTracker/JiraIssueWriter.js';

/** Creates a mock ConfigProvider with Jira config. */
const createMockConfig = (): ConfigProvider => ({
    getRequired: vi.fn().mockImplementation((key: string) => {
        const map: Record<string, string> = {
            JIRA_BASE_URL: 'https://test.atlassian.net',
            JIRA_USER_EMAIL: 'test@example.com',
            JIRA_API_TOKEN: 'test-token',
        };
        return map[key] ?? 'default';
    }),
    getOptional: vi.fn(),
    getRequiredNumber: vi.fn(),
    getOptionalNumber: vi.fn(),
});

/** Creates a mock Logger. */
const createMockLogger = (): Logger => ({
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    debug: vi.fn(),
    child: vi.fn().mockReturnThis(),
});

describe('JiraIssueWriter', () => {
    let writer: JiraIssueWriter;
    let fetchMock: ReturnType<typeof vi.fn>;

    beforeEach(() => {
        fetchMock = vi.fn();
        global.fetch = fetchMock;
        writer = new JiraIssueWriter(createMockConfig(), createMockLogger());
    });

    describe('transitionStatus', () => {
        it('should look up transition ID and call transitions API', async () => {
            // First call: get transitions
            fetchMock.mockResolvedValueOnce({
                ok: true,
                json: () => Promise.resolve({
                    transitions: [
                        { id: '31', name: 'To Investigation', to: { name: 'Issue Investigation' } },
                        { id: '41', name: 'To Plan', to: { name: 'Plan' } },
                    ],
                }),
            });
            // Second call: post transition
            fetchMock.mockResolvedValueOnce({ ok: true });

            await writer.transitionStatus('TEST-1', 'Issue Investigation');

            expect(fetchMock).toHaveBeenCalledTimes(2);
            const secondCall = fetchMock.mock.calls[1];
            const body = JSON.parse(secondCall[1].body as string);
            expect(body.transition.id).toBe('31');
        });

        it('should throw IntegrationError when no matching transition found', async () => {
            fetchMock.mockResolvedValueOnce({
                ok: true,
                json: () => Promise.resolve({
                    transitions: [{ id: '31', name: 'Other', to: { name: 'Other Status' } }],
                }),
            });

            await expect(writer.transitionStatus('TEST-1', 'Nonexistent Status'))
                .rejects.toThrow(IntegrationError);
        });

        it('should throw IntegrationError on API failure', async () => {
            fetchMock.mockResolvedValueOnce({ ok: false, status: 500 });
            await expect(writer.transitionStatus('TEST-1', 'Plan')).rejects.toThrow(IntegrationError);
        });

        it('should match transition by case-insensitive name', async () => {
            fetchMock.mockResolvedValueOnce({
                ok: true,
                json: () => Promise.resolve({
                    transitions: [{ id: '31', name: 'Start Investigation', to: { name: 'issue investigation' } }],
                }),
            });
            fetchMock.mockResolvedValueOnce({ ok: true });

            await expect(writer.transitionStatus('TEST-1', 'Issue Investigation')).resolves.not.toThrow();
        });
    });

    describe('addComment', () => {
        it('should post a comment in ADF format', async () => {
            fetchMock.mockResolvedValue({ ok: true });

            await writer.addComment('TEST-1', 'Hello world');

            expect(fetchMock).toHaveBeenCalledTimes(1);
            const [url, options] = fetchMock.mock.calls[0];
            expect(url).toContain('/rest/api/3/issue/TEST-1/comment');
            expect(options.method).toBe('POST');
            const body = JSON.parse(options.body as string);
            expect(body.body.type).toBe('doc');
            expect(body.body.content[0].content[0].text).toBe('Hello world');
        });

        it('should throw IntegrationError on failure', async () => {
            fetchMock.mockResolvedValue({ ok: false, status: 400 });
            await expect(writer.addComment('TEST-1', 'fail')).rejects.toThrow(IntegrationError);
        });

        it('should throw IntegrationError on network error', async () => {
            fetchMock.mockRejectedValue(new Error('Network error'));
            await expect(writer.addComment('TEST-1', 'fail')).rejects.toThrow(IntegrationError);
        });
    });

    describe('updateCustomField', () => {
        it('should send PUT request with field value', async () => {
            fetchMock.mockResolvedValue({ ok: true });

            await writer.updateCustomField('TEST-1', 'description_for_ai', 'AI desc');

            expect(fetchMock).toHaveBeenCalledTimes(1);
            const [url, options] = fetchMock.mock.calls[0];
            expect(url).toContain('/rest/api/3/issue/TEST-1');
            expect(options.method).toBe('PUT');
            const body = JSON.parse(options.body as string);
            expect(body.fields.description_for_ai).toBe('AI desc');
        });

        it('should throw IntegrationError on failure', async () => {
            fetchMock.mockResolvedValue({ ok: false, status: 400 });
            await expect(writer.updateCustomField('TEST-1', 'field', 'value')).rejects.toThrow(IntegrationError);
        });

        it('should throw IntegrationError on network error', async () => {
            fetchMock.mockRejectedValue(new Error('Network error'));
            await expect(writer.updateCustomField('TEST-1', 'field', 'value')).rejects.toThrow(IntegrationError);
        });
    });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import type { IssueReader, IssueWriter, Logger } from '@hcdevagent/shared';
import { WORKFLOW_STATUSES, JIRA_CUSTOM_FIELDS } from '@hcdevagent/shared';
import { IssueTrackerModule } from '../../modules/issueTracker/IssueTrackerModule.js';
import { testIssue } from '../fixtures/testIssue.fixture.js';

/** Creates a mock Logger. */
const createMockLogger = (): Logger => ({
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    debug: vi.fn(),
    child: vi.fn().mockReturnThis(),
});

describe('IssueTrackerModule', () => {
    let module: IssueTrackerModule;
    let reader: IssueReader;
    let writer: IssueWriter;

    beforeEach(() => {
        reader = {
            fetchIssuesByStatus: vi.fn().mockResolvedValue([]),
            getIssue: vi.fn().mockResolvedValue(testIssue),
            getComments: vi.fn().mockResolvedValue([]),
            getLatestComment: vi.fn().mockResolvedValue(null),
            getCustomField: vi.fn().mockResolvedValue(null),
            getStatus: vi.fn().mockResolvedValue(WORKFLOW_STATUSES.SELECTED_FOR_TRIAGE),
        };

        writer = {
            transitionStatus: vi.fn().mockResolvedValue(undefined),
            addComment: vi.fn().mockResolvedValue(undefined),
            updateCustomField: vi.fn().mockResolvedValue(undefined),
        };

        module = new IssueTrackerModule(reader, writer, createMockLogger());
    });

    describe('fetchNextIssue', () => {
        it('should return null when no issues found', async () => {
            const result = await module.fetchNextIssue();
            expect(result).toBeNull();
            expect(reader.fetchIssuesByStatus).toHaveBeenCalledWith(WORKFLOW_STATUSES.SELECTED_FOR_TRIAGE);
        });

        it('should return the first issue when issues are found', async () => {
            (reader.fetchIssuesByStatus as ReturnType<typeof vi.fn>).mockResolvedValue([testIssue]);
            const result = await module.fetchNextIssue();
            expect(result).toEqual(testIssue);
        });
    });

    describe('startInvestigation', () => {
        it('should transition to ISSUE INVESTIGATION', async () => {
            await module.startInvestigation('TEST-1');
            expect(writer.transitionStatus).toHaveBeenCalledWith('TEST-1', WORKFLOW_STATUSES.ISSUE_INVESTIGATION);
        });
    });

    describe('markBlockedForPlanClarification', () => {
        it('should transition and add comment', async () => {
            await module.markBlockedForPlanClarification('TEST-1', 'What is the scope?');
            expect(writer.transitionStatus).toHaveBeenCalledWith('TEST-1', WORKFLOW_STATUSES.BLOCKED_FOR_PLAN_CLARIFICATION);
            expect(writer.addComment).toHaveBeenCalledWith('TEST-1', 'What is the scope?');
        });
    });

    describe('moveToPlan', () => {
        it('should write description for AI and transition to PLAN', async () => {
            await module.moveToPlan('TEST-1', 'AI description');
            expect(writer.updateCustomField).toHaveBeenCalledWith(
                'TEST-1',
                JIRA_CUSTOM_FIELDS.DESCRIPTION_FOR_AI,
                'AI description',
            );
            expect(writer.transitionStatus).toHaveBeenCalledWith('TEST-1', WORKFLOW_STATUSES.PLAN);
        });
    });

    describe('markFailed', () => {
        it('should write failure reason, transition to FAILURE, and add comment', async () => {
            await module.markFailed('TEST-1', 'Unrecoverable error');
            expect(writer.updateCustomField).toHaveBeenCalledWith(
                'TEST-1',
                JIRA_CUSTOM_FIELDS.FAILURE_REASON,
                'Unrecoverable error',
            );
            expect(writer.transitionStatus).toHaveBeenCalledWith('TEST-1', WORKFLOW_STATUSES.FAILURE);
            expect(writer.addComment).toHaveBeenCalledWith('TEST-1', 'Agent failure: Unrecoverable error');
        });
    });

    describe('getCurrentStatus', () => {
        it('should delegate to reader.getStatus', async () => {
            (reader.getStatus as ReturnType<typeof vi.fn>).mockResolvedValue(WORKFLOW_STATUSES.PLAN);
            const status = await module.getCurrentStatus('TEST-1');
            expect(status).toBe(WORKFLOW_STATUSES.PLAN);
        });
    });

    describe('getLatestHumanReply', () => {
        it('should delegate to reader.getLatestComment', async () => {
            const comment = { id: '1', author: 'Human', body: 'Reply', createdAt: '2026-01-01' };
            (reader.getLatestComment as ReturnType<typeof vi.fn>).mockResolvedValue(comment);
            const result = await module.getLatestHumanReply('TEST-1');
            expect(result).toEqual(comment);
        });
    });

    describe('read convenience methods', () => {
        it('getDescriptionForAi should read the correct custom field', async () => {
            await module.getDescriptionForAi('TEST-1');
            expect(reader.getCustomField).toHaveBeenCalledWith('TEST-1', JIRA_CUSTOM_FIELDS.DESCRIPTION_FOR_AI);
        });

        it('getPlan should read the correct custom field', async () => {
            await module.getPlan('TEST-1');
            expect(reader.getCustomField).toHaveBeenCalledWith('TEST-1', JIRA_CUSTOM_FIELDS.IMPLEMENTATION_PLAN);
        });

        it('getPlanForAi should read the correct custom field', async () => {
            await module.getPlanForAi('TEST-1');
            expect(reader.getCustomField).toHaveBeenCalledWith('TEST-1', JIRA_CUSTOM_FIELDS.IMPLEMENTATION_PLAN_FOR_AI);
        });

        it('getBranchName should read the correct custom field', async () => {
            await module.getBranchName('TEST-1');
            expect(reader.getCustomField).toHaveBeenCalledWith('TEST-1', JIRA_CUSTOM_FIELDS.BRANCH_NAME);
        });

        it('getPrUrl should read the correct custom field', async () => {
            await module.getPrUrl('TEST-1');
            expect(reader.getCustomField).toHaveBeenCalledWith('TEST-1', JIRA_CUSTOM_FIELDS.PR_URL);
        });
    });

    describe('not-yet-implemented methods', () => {
        it('moveToPlanReview should throw NotImplementedError', async () => {
            await expect(module.moveToPlanReview('TEST-1', 'plan', 'planForAi')).rejects.toThrow('not yet implemented');
        });

        it('startImplementation should throw NotImplementedError', async () => {
            await expect(module.startImplementation('TEST-1', 'branch')).rejects.toThrow('not yet implemented');
        });

        it('markDone should throw NotImplementedError', async () => {
            await expect(module.markDone('TEST-1')).rejects.toThrow('not yet implemented');
        });
    });
});

import { describe, it, expect } from 'vitest';
import { StubIssueInvestigator } from '../../modules/investigation/OpenAiIssueInvestigator.js';
import { testIssue } from '../fixtures/testIssue.fixture.js';

describe('StubIssueInvestigator', () => {
    const investigator = new StubIssueInvestigator();

    it('should always return ready: true', async () => {
        const result = await investigator.investigate(testIssue);
        expect(result.ready).toBe(true);
    });

    it('should return a non-null descriptionForAi', async () => {
        const result = await investigator.investigate(testIssue);
        expect(result.descriptionForAi).toBeTruthy();
        expect(typeof result.descriptionForAi).toBe('string');
    });

    it('should return null clarificationQuestions', async () => {
        const result = await investigator.investigate(testIssue);
        expect(result.clarificationQuestions).toBeNull();
    });

    it('should return an all-passed quality report', async () => {
        const result = await investigator.investigate(testIssue);
        const { qualityReport } = result;
        expect(qualityReport.clarity.passed).toBe(true);
        expect(qualityReport.completeness.passed).toBe(true);
        expect(qualityReport.ambiguity.passed).toBe(true);
        expect(qualityReport.specificity.passed).toBe(true);
        expect(qualityReport.conflictDetection.passed).toBe(true);
        expect(qualityReport.scope.passed).toBe(true);
    });

    it('should include the issue summary in the description', async () => {
        const result = await investigator.investigate(testIssue);
        expect(result.descriptionForAi).toContain(testIssue.summary);
    });

    it('should include the issue key in the description', async () => {
        const result = await investigator.investigate(testIssue);
        expect(result.descriptionForAi).toContain(testIssue.key);
    });

    it('should work with relatedIssues parameter', async () => {
        const result = await investigator.investigate(testIssue, [testIssue]);
        expect(result.ready).toBe(true);
    });
});

import { describe, it, expect } from 'vitest';
import { SYMBOLS } from '@hcdevagent/shared';
import { container } from '../container.js';
import { createTestContainer } from './helpers/createTestContainer.js';

describe('agent package smoke test', () => {
  it('should export container', () => {
    expect(container).toBeDefined();
  });

  it('should resolve Logger from the production container', () => {
    const logger = container.get(SYMBOLS.Logger);
    expect(logger).toBeDefined();
  });

  it('should resolve ConfigProvider from the production container', () => {
    const configProvider = container.get(SYMBOLS.ConfigProvider);
    expect(configProvider).toBeDefined();
  });

  it('should resolve EventBus from the production container', () => {
    const eventBus = container.get(SYMBOLS.EventBus);
    expect(eventBus).toBeDefined();
  });

  it('should create a test container with mock implementations', () => {
    const testContainer = createTestContainer();
    expect(testContainer).toBeDefined();

    const logger = testContainer.get(SYMBOLS.Logger);
    expect(logger).toBeDefined();

    const configProvider = testContainer.get(SYMBOLS.ConfigProvider);
    expect(configProvider).toBeDefined();
  });

  it('should allow rebinding in test container', () => {
    const customLogger = { debug: () => {}, info: () => {}, warn: () => {}, error: () => {}, child: () => customLogger };
    const testContainer = createTestContainer((c) => {
      c.rebind(SYMBOLS.Logger).toConstantValue(customLogger);
    });

    const logger = testContainer.get(SYMBOLS.Logger);
    expect(logger).toBe(customLogger);
  });
});

