import type { PlanResult, QualityReport } from '../types/phases.types.js';

/**
 * Implements code changes based on a plan.
 */
export interface CodeImplementer {
  /** Implements the plan and returns a quality report. */
  implement(plan: PlanResult): Promise<QualityReport>;
}

import type { CodeChanges, CodebaseContext } from '../types/domain.types.js';

/**
 * Generates code changes based on an approved plan.
 * Matches 3-interfaces.md §6.
 */
export interface CodeImplementer {
    /** Generate code changes for the full plan. */
    implementPlan(planForAi: string, codebase: CodebaseContext): Promise<CodeChanges>;

    /** Re-generate code incorporating PR review feedback. */
    applyPrFeedback(planForAi: string, codebase: CodebaseContext, reviewComments: string): Promise<CodeChanges>;

    /** Continue implementation after human clarification. */
    answerClarification(planForAi: string, codebase: CodebaseContext, clarification: string): Promise<CodeChanges>;
}

/**
 * In-process event bus for decoupled communication between modules.
 */
export interface EventBus {
  /** Publishes an event with an optional payload. */
  publish(eventName: string, payload: unknown): void;

  /** Subscribes a handler to an event. */
  subscribe(eventName: string, handler: (payload: unknown) => void): void;

  /** Unsubscribes a handler from an event. */
  unsubscribe(eventName: string, handler: (payload: unknown) => void): void;
}

/**
 * In-process typed pub/sub system.
 * Matches 3-interfaces.md §9.
 */
export interface EventBus {
    /** Publish an event to all registered listeners. */
    emit(eventName: string, payload: unknown): void;

    /** Register a listener for an event. */
    on(eventName: string, handler: (payload: unknown) => void): void;

    /** Remove a previously registered listener. */
    off(eventName: string, handler: (payload: unknown) => void): void;
}

import type { Issue } from '../types/domain.types.js';
import type { InvestigationResult } from '../types/phases.types.js';

/**
 * Investigates an issue to extract acceptance criteria and approach.
 */
export interface IssueInvestigator {
  /** Analyzes an issue and produces an investigation result. */
  investigate(issue: Issue): Promise<InvestigationResult>;
}

import type { Issue } from '../types/domain.types.js';
import type { InvestigationResult } from '../types/phases.types.js';

/**
 * Analyses a raw issue to determine whether it is ready for planning.
 * Called by the Conductor during Phase 1 (Investigation).
 * Matches 3-interfaces.md §4.
 */
export interface IssueInvestigator {
    /** Run all quality checks on the issue and produce a verdict. */
    investigate(issue: Issue, relatedIssues?: ReadonlyArray<Issue>): Promise<InvestigationResult>;
}

import type { Issue } from '../types/domain.types.js';

/**
 * Reads issues from an issue tracker system.
 */
export interface IssueReader {
  /** Fetches a single issue by its key. */
  getIssue(issueKey: string): Promise<Issue>;

  /** Fetches issues matching a given query or filter. */
  getIssues(query: string): Promise<ReadonlyArray<Issue>>;
}

import type { Issue } from '../types/domain.types.js';
import type { Comment } from '../types/domain.types.js';

/**
 * Low-level read adapter for the issue tracker (e.g., Jira REST API).
 * Matches 3-interfaces.md §1.
 */
export interface IssueReader {
    /** Fetch all issues currently in the given workflow status. */
    fetchIssuesByStatus(statusName: string): Promise<ReadonlyArray<Issue>>;

    /** Fetch full issue details by key. */
    getIssue(issueKey: string): Promise<Issue>;

    /** Fetch all comments on an issue, ordered chronologically. */
    getComments(issueKey: string): Promise<ReadonlyArray<Comment>>;

    /** Fetch the most recent comment (used to read human replies). */
    getLatestComment(issueKey: string): Promise<Comment | null>;

    /** Read the value of a custom field. */
    getCustomField(issueKey: string, fieldName: string): Promise<string | null>;

    /** Read the current workflow status of an issue. */
    getStatus(issueKey: string): Promise<string>;
}

import type { IssueReader } from './IssueReader.js';
import type { IssueWriter } from './IssueWriter.js';

/**
 * Combined issue tracker operations interface.
 * Extends both reader and writer capabilities.
 */
export interface IssueTrackerOperations extends IssueReader, IssueWriter {}

import type { Issue, Comment } from '../types/domain.types.js';

/**
 * High-level, workflow-aware interface consumed by the Conductor.
 * Each method internally composes one or more IssueReader/IssueWriter calls.
 * Matches 3-interfaces.md §3.
 */
export interface IssueTrackerOperations {
    /** Poll for the next issue in SELECTED FOR TRIAGE status. */
    fetchNextIssue(): Promise<Issue | null>;

    /** Transition issue to ISSUE INVESTIGATION. */
    startInvestigation(issueKey: string): Promise<void>;

    /** Transition to BLOCKED FOR PLAN CLARIFICATION + post comment with questions. */
    markBlockedForPlanClarification(issueKey: string, questions: string): Promise<void>;

    /** Write Description For AI field + transition to PLAN. */
    moveToPlan(issueKey: string, descriptionForAi: string): Promise<void>;

    /** Write Implementation Plan + Implementation Plan For AI fields + transition to PLAN REVIEW. */
    moveToPlanReview(issueKey: string, plan: string, planForAi: string): Promise<void>;

    /** Transition to IN PROGRESS + write Branch Name field. */
    startImplementation(issueKey: string, branchName: string): Promise<void>;

    /** Transition to BLOCKED FOR CODE CLARIFICATION + post comment with questions. */
    markBlockedForCodeClarification(issueKey: string, questions: string): Promise<void>;

    /** Transition to IN PROGRESS (after code clarification resolved). */
    resumeImplementation(issueKey: string): Promise<void>;

    /** Transition to CODE COMMITTED. */
    markCodeCommitted(issueKey: string): Promise<void>;

    /** Transition to PR IN REVIEW + write PR URL field + comment with PR URL. */
    markPrInReview(issueKey: string, prUrl: string): Promise<void>;

    /** Transition to PR APPROVED. */
    markPrApproved(issueKey: string): Promise<void>;

    /** Transition to DONE. */
    markDone(issueKey: string): Promise<void>;

    /** Transition to PR CHANGES REQUESTED + comment. */
    markPrChangesRequested(issueKey: string, reviewComment: string): Promise<void>;

    /** Transition to FAILURE + write Failure Reason field + comment. */
    markFailed(issueKey: string, reason: string): Promise<void>;

    /** Read Description For AI custom field. */
    getDescriptionForAi(issueKey: string): Promise<string | null>;

    /** Read Implementation Plan custom field. */
    getPlan(issueKey: string): Promise<string | null>;

    /** Read Implementation Plan For AI custom field. */
    getPlanForAi(issueKey: string): Promise<string | null>;

    /** Read Branch Name custom field. */
    getBranchName(issueKey: string): Promise<string | null>;

    /** Read PR URL custom field. */
    getPrUrl(issueKey: string): Promise<string | null>;

    /** Read the latest human comment (for clarification responses). */
    getLatestHumanReply(issueKey: string): Promise<Comment | null>;

    /** Read current status (for detecting cancellation / external changes). */
    getCurrentStatus(issueKey: string): Promise<string>;
}

/**
 * Writes updates to an issue tracker system.
 */
export interface IssueWriter {
  /** Transitions an issue to a new status. */
  transitionIssue(issueKey: string, targetStatus: string): Promise<void>;

  /** Adds a comment to an issue. */
  addComment(issueKey: string, body: string): Promise<void>;

  /** Updates custom fields on an issue. */
  updateFields(issueKey: string, fields: Record<string, unknown>): Promise<void>;
}

/**
 * Low-level write adapter for the issue tracker (e.g., Jira REST API).
 * Matches 3-interfaces.md §2.
 */
export interface IssueWriter {
    /** Move the issue to a new workflow status. */
    transitionStatus(issueKey: string, statusName: string): Promise<void>;

    /** Post a comment on the issue. */
    addComment(issueKey: string, body: string): Promise<void>;

    /** Write a value to a custom Jira field. */
    updateCustomField(issueKey: string, fieldName: string, value: string): Promise<void>;
}

/**
 * Logger abstraction for structured logging.
 */
export interface Logger {
  /** Logs a debug-level message. */
  debug(message: string, context?: Record<string, unknown>): void;

  /** Logs an info-level message. */
  info(message: string, context?: Record<string, unknown>): void;

  /** Logs a warn-level message. */
  warn(message: string, context?: Record<string, unknown>): void;

  /** Logs an error-level message. */
  error(message: string, context?: Record<string, unknown>): void;

  /** Creates a child logger with additional context. */
  child(context: Record<string, unknown>): Logger;
}

/**
 * Logger abstraction for structured logging.
 * Matches 3-interfaces.md §11.
 */
export interface Logger {
    /** Logs a debug-level message. */
    debug(message: string, context?: Record<string, unknown>): void;

    /** Logs an info-level message. */
    info(message: string, context?: Record<string, unknown>): void;

    /** Logs a warn-level message. */
    warn(message: string, context?: Record<string, unknown>): void;

    /** Logs an error-level message with optional Error object. */
    error(message: string, error?: Error, context?: Record<string, unknown>): void;

    /** Creates a child logger with additional context. */
    child(context: Record<string, unknown>): Logger;
}

import type { InvestigationResult } from '../types/phases.types.js';
import type { PlanResult } from '../types/phases.types.js';

/**
 * Generates an implementation plan from investigation results.
 */
export interface PlanGenerator {
  /** Generates a step-by-step plan for implementing the issue. */
  generatePlan(investigation: InvestigationResult): Promise<PlanResult>;
}

import type { PlanResult } from '../types/phases.types.js';

/**
 * Generates implementation plans from the enhanced Description For AI.
 * Matches 3-interfaces.md §5.
 */
export interface PlanGenerator {
    /** Generate both plan formats from the enhanced description. */
    generatePlan(descriptionForAi: string, feedback?: string): Promise<PlanResult>;

    /** Re-generate both plans incorporating human rejection feedback. */
    refinePlan(existingPlanForAi: string, rejectionComment: string): Promise<PlanResult>;
}

import type { ActiveIssue, ExecutionLogEntry, PhaseMetric } from '../types/storage.types.js';

/**
 * Abstraction for persistent storage operations.
 */
export interface StorageAdapter {
  /** Saves or updates an active issue record. */
  upsertActiveIssue(activeIssue: ActiveIssue): Promise<void>;

  /** Retrieves an active issue by its key. */
  getActiveIssue(issueKey: string): Promise<ActiveIssue | null>;

  /** Removes an active issue record. */
  removeActiveIssue(issueKey: string): Promise<void>;

  /** Retrieves all currently active issues. */
  getAllActiveIssues(): Promise<ReadonlyArray<ActiveIssue>>;

  /** Appends an execution log entry. */
  appendLog(entry: ExecutionLogEntry): Promise<void>;

  /** Retrieves execution logs for an issue. */
  getLogs(issueKey: string): Promise<ReadonlyArray<ExecutionLogEntry>>;

  /** Records a phase metric. */
  recordMetric(metric: PhaseMetric): Promise<void>;
}

import type { ActiveIssue, ExecutionLogEntry, PhaseMetric } from '../types/storage.types.js';

/**
 * Abstracts database operations for agent-internal data.
 * Matches 3-interfaces.md §8.
 */
export interface StorageAdapter {
    /** Fetch the currently active issue record. */
    getActiveIssue(): Promise<ActiveIssue | null>;

    /** Create or update the active issue record. */
    setActiveIssue(record: ActiveIssue): Promise<void>;

    /** Remove the active issue record (done / cancelled / failed). */
    clearActiveIssue(issueKey: string): Promise<void>;

    /** Append an audit log entry. */
    addExecutionLog(entry: ExecutionLogEntry): Promise<void>;

    /** Fetch execution history, optionally filtered by issue. */
    getExecutionHistory(issueKey?: string): Promise<ReadonlyArray<ExecutionLogEntry>>;

    /** Insert or update a phase metric record. */
    addMetric(metric: PhaseMetric): Promise<void>;

    /** Update an in-progress metric. */
    updateMetric(issueKey: string, phase: string, update: Partial<PhaseMetric>): Promise<void>;

    /** Fetch metrics, optionally filtered by issue. */
    getMetrics(issueKey?: string): Promise<ReadonlyArray<PhaseMetric>>;

    /** Read a runtime config override from the database. */
    getConfigOverride(key: string): Promise<unknown | null>;

    /** Upsert a runtime config override. */
    setConfigOverride(key: string, value: unknown, updatedBy?: string): Promise<void>;
}

import type { PullRequest } from '../types/domain.types.js';

/**
 * Manages version control operations (branches, commits, PRs).
 */
export interface VersionControl {
  /** Creates a new branch from the default branch. */
  createBranch(branchName: string): Promise<void>;

  /** Commits changes to the current branch. */
  commitChanges(message: string, files: ReadonlyArray<string>): Promise<string>;

  /** Creates a pull request. */
  createPullRequest(
    title: string,
    description: string,
    sourceBranch: string,
  ): Promise<PullRequest>;

  /** Gets the status of a pull request by ID. */
  getPullRequestStatus(prId: string): Promise<string>;
}

import type { CodeChanges, PrOptions, PrStatus, PullRequest } from '../types/domain.types.js';

/**
 * Abstracts Git operations and remote platform API (e.g., GitHub).
 * Matches 3-interfaces.md §7.
 */
export interface VersionControl {
    /** Create a new feature branch from base (default: main). */
    createBranch(branchName: string, baseBranch?: string): Promise<void>;

    /** Stage file modifications in the working tree. */
    applyChanges(changes: CodeChanges): Promise<void>;

    /** Commit staged changes, returns commit SHA. */
    commit(message: string): Promise<string>;

    /** Push branch to remote. */
    push(branchName: string): Promise<void>;

    /** Open a PR on the remote platform. */
    createPullRequest(options: PrOptions): Promise<PullRequest>;

    /** Check PR state (open, merged, changes requested). */
    getPullRequestStatus(prId: string): Promise<PrStatus>;

    /** Delete remote and local branch (cleanup after merge). */
    deleteBranch(branchName: string): Promise<void>;
}

