/**
 * Phase result types for each agent workflow phase.
 */

import type { CodeChanges } from './domain.types.js';

/** Result of the investigation phase. */
export interface InvestigationResult {
  readonly issueKey: string;
  readonly summary: string;
  readonly analysis: string;
  readonly acceptanceCriteria: ReadonlyArray<string>;
  readonly suggestedApproach: string;
}

/** A single step in a generated plan. */
export interface PlanStep {
  readonly order: number;
  readonly description: string;
  readonly filePath: string | null;
  readonly estimatedComplexity: 'low' | 'medium' | 'high';
}

/** Result of the planning phase. */
export interface PlanResult {
  readonly issueKey: string;
  readonly steps: ReadonlyArray<PlanStep>;
  readonly estimatedFiles: ReadonlyArray<string>;
  readonly testStrategy: string;
}

/** Quality report produced after implementation. */
export interface QualityReport {
  readonly issueKey: string;
  readonly passedTests: number;
  readonly failedTests: number;
  readonly coveragePercentage: number;
  readonly lintErrors: number;
  readonly codeChanges: ReadonlyArray<CodeChanges>;
  readonly overallStatus: 'pass' | 'fail';
}

/**
 * Phase result types for each agent workflow phase.
 * Matches 3-interfaces.md §4, §5, §6.
 */

/** Result of a single quality check during investigation. */
export interface CheckResult {
    readonly passed: boolean;
    readonly summary: string;
}

/** Detailed breakdown of each quality check during investigation. */
export interface QualityReport {
    readonly clarity: CheckResult;
    readonly completeness: CheckResult;
    readonly ambiguity: CheckResult;
    readonly specificity: CheckResult;
    readonly conflictDetection: CheckResult;
    readonly scope: CheckResult;
}

/** Result of the investigation phase (3-interfaces.md §4). */
export interface InvestigationResult {
    readonly ready: boolean;
    readonly descriptionForAi: string | null;
    readonly clarificationQuestions: ReadonlyArray<string> | null;
    readonly qualityReport: QualityReport;
}

/** Result of the planning phase (3-interfaces.md §5). */
export interface PlanResult {
    readonly plan: string;
    readonly planForAi: string;
}

/**
 * Storage-related types for persistence layer.
 */

/** Represents an issue currently being processed by the agent. */
export interface ActiveIssue {
  readonly issueKey: string;
  readonly currentPhase: string;
  readonly startedAt: string;
  readonly updatedAt: string;
  readonly retryCount: number;
  readonly metadata: Record<string, unknown>;
}

/** Represents a single execution log entry. */
export interface ExecutionLogEntry {
  readonly id: string;
  readonly issueKey: string;
  readonly phase: string;
  readonly status: 'started' | 'completed' | 'failed';
  readonly message: string;
  readonly timestamp: string;
  readonly durationMs: number | null;
}

/** Metrics for a single phase execution. */
export interface PhaseMetric {
  readonly issueKey: string;
  readonly phase: string;
  readonly startedAt: string;
  readonly completedAt: string | null;
  readonly durationMs: number | null;
  readonly success: boolean;
  readonly errorMessage: string | null;
}

/**
 * Storage-related types for persistence layer.
 * Matches 3-interfaces.md §8.
 */

/** Represents the currently active issue being processed by the agent. */
export interface ActiveIssue {
    readonly issueKey: string;
    readonly phase: string;
    readonly agentId: string;
    readonly currentStep: string | null;
    readonly branchName: string | null;
    readonly prUrl: string | null;
    readonly retryCount: number;
    readonly lastError: string | null;
    readonly startedAt: string;
    readonly updatedAt: string;
}

/** Represents a single execution log entry for audit purposes. */
export interface ExecutionLogEntry {
    readonly issueKey: string;
    readonly action: string;
    readonly timestamp: string;
    readonly phase: string;
    readonly details: string;
    readonly outcome: 'success' | 'failure' | 'skipped';
    readonly durationMs: number | null;
    readonly errorMessage: string | null;
}

/** Metrics for a single phase execution. */
export interface PhaseMetric {
    readonly issueKey: string;
    readonly phase: string;
    readonly startedAt: string;
    readonly completedAt: string | null;
    readonly durationMs: number | null;
    readonly aiTokensUsed: number;
    readonly aiCallCount: number;
    readonly retryCount: number;
    readonly outcome: 'success' | 'failure' | 'in_progress';
}
